do $funding_checkpoint_56$ begin
update company_funding_rounds set (announced_date,financing_type,note_en,checked_at)=('2026-02-17','undisclosed','Neo Autonomy''s launch release names Fadron among its initial investments by 17 February 2026. The financing instrument, amount, stake and closing date are undisclosed.','2026-11-05'::date) where id='3bdb96cc-2b46-4217-874b-1a9999c6c2bf' and round_key='neo-autonomy-investment-2026' and amount is null and publication_status='approved' and row(announced_date,financing_type,note_en,checked_at::text)=row('2026-06-03','equity','The investor announcement confirms Fadron as an investment but does not disclose the amount, stake, instrument details or exact closing date; the announcement date is used.','2026-11-03'); if not exists(select 1 from company_funding_rounds where id='3bdb96cc-2b46-4217-874b-1a9999c6c2bf' and round_key='neo-autonomy-investment-2026' and amount is null and publication_status='approved' and row(announced_date,financing_type,note_en,checked_at::text)=row('2026-02-17','undisclosed','Neo Autonomy''s launch release names Fadron among its initial investments by 17 February 2026. The financing instrument, amount, stake and closing date are undisclosed.','2026-11-05')) then raise exception 'Unexpected correction baseline: neo-autonomy-investment-2026'; end if; insert into company_funding_round_sources(round_id,url,title,source_type,checked_at) values('3bdb96cc-2b46-4217-874b-1a9999c6c2bf','https://www.issuewire.com/neo-ventures-team-launches-neo-autonomy-a-new-investment-fund-focused-on-transport-logistics-and-autonomous-systems-1857373980204693','Neo Ventures launch release naming Fadron among initial investments','investor_announcement','2026-11-05'::date) on conflict(round_id,url) do nothing;
update company_funding_rounds set (announced_date,financing_type,note_en,checked_at)=('2001-07-25','equity','General Dynamics reported that it acquired Empresa Nacional Santa Bárbara de Industrias Militares and Santa Bárbara Blindados on 25 July 2001. The acquired companies were combined as Santa Bárbara Sistemas. The date is completion. Individual transaction consideration and primary proceeds are undisclosed.','2026-11-05'::date) where id='6c50567e-21eb-4704-9eb1-11cd19c5b372' and round_key='general-dynamics-acquisition-2001' and amount is null and publication_status='approved' and row(announced_date,financing_type,note_en,checked_at::text)=row('2001','equity','The group history confirms continuity from Empresa Nacional Santa Bárbara to Santa Bárbara Sistemas within General Dynamics. Consideration and exact completion date are not disclosed on the checked source.','2026-11-03'); if not exists(select 1 from company_funding_rounds where id='6c50567e-21eb-4704-9eb1-11cd19c5b372' and round_key='general-dynamics-acquisition-2001' and amount is null and publication_status='approved' and row(announced_date,financing_type,note_en,checked_at::text)=row('2001-07-25','equity','General Dynamics reported that it acquired Empresa Nacional Santa Bárbara de Industrias Militares and Santa Bárbara Blindados on 25 July 2001. The acquired companies were combined as Santa Bárbara Sistemas. The date is completion. Individual transaction consideration and primary proceeds are undisclosed.','2026-11-05')) then raise exception 'Unexpected correction baseline: general-dynamics-acquisition-2001'; end if; insert into company_funding_round_sources(round_id,url,title,source_type,checked_at) values('6c50567e-21eb-4704-9eb1-11cd19c5b372','https://www.sec.gov/Archives/edgar/data/40533/000095013302001284/w58696ex13.htm','General Dynamics 2001 annual report, business combinations note','investor_announcement','2026-11-05'::date) on conflict(round_id,url) do nothing;
update investor_companies j set evidence_status='investor_published_portfolio' from companies c, investor_research i where j.company_id=c.id and j.investor_research_id=i.id and c.slug='verity' and i.slug='helvetica-capital' and j.source_url='https://www.helvetica-capital.ch/en/portfolio/verity' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed' and j.evidence_status<>'investor_published_portfolio';
if not exists(select 1 from investor_companies j join companies c on c.id=j.company_id join investor_research i on i.id=j.investor_research_id where c.slug='verity' and i.slug='helvetica-capital' and j.source_url='https://www.helvetica-capital.ch/en/portfolio/verity' and j.evidence_status='investor_published_portfolio' and j.relationship_type='portfolio_listed') then raise exception 'Manifest relationship did not match: verity/helvetica-capital'; end if;
update investor_companies j set evidence_status='company_published_investors' from companies c, investor_research i where j.company_id=c.id and j.investor_research_id=i.id and c.slug='fixar-fixar-aero-llc' and i.slug='the-untitled-ventures' and j.source_url='https://cancham.lv/docs/961/Presentations/220530_LCCI_FIXAR_Way_to_Canada.pdf' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed' and j.evidence_status<>'company_published_investors';
if not exists(select 1 from investor_companies j join companies c on c.id=j.company_id join investor_research i on i.id=j.investor_research_id where c.slug='fixar-fixar-aero-llc' and i.slug='the-untitled-ventures' and j.source_url='https://cancham.lv/docs/961/Presentations/220530_LCCI_FIXAR_Way_to_Canada.pdf' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed') then raise exception 'Manifest relationship did not match: fixar-fixar-aero-llc/the-untitled-ventures'; end if;
update investor_companies j set evidence_status='third_party_reported' from companies c, investor_research i where j.company_id=c.id and j.investor_research_id=i.id and c.slug='gurzuf-defence' and i.slug='resist-ua' and j.source_url='https://nv.ua/ukr/amp/droni-finansist-pro-vkladannya-u-bezpilotniki-problemi-opk-i-perspektivi-novini-ukrajini-50396283.html' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed' and j.evidence_status<>'third_party_reported';
if not exists(select 1 from investor_companies j join companies c on c.id=j.company_id join investor_research i on i.id=j.investor_research_id where c.slug='gurzuf-defence' and i.slug='resist-ua' and j.source_url='https://nv.ua/ukr/amp/droni-finansist-pro-vkladannya-u-bezpilotniki-problemi-opk-i-perspektivi-novini-ukrajini-50396283.html' and j.evidence_status='third_party_reported' and j.relationship_type='portfolio_listed') then raise exception 'Manifest relationship did not match: gurzuf-defence/resist-ua'; end if;
update investor_companies j set evidence_status='company_published_investors' from companies c, investor_research i where j.company_id=c.id and j.investor_research_id=i.id and c.slug='germandrones' and i.slug='klaus-scho' and j.source_url='https://www.germandrones.com/en/contact' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed' and j.evidence_status<>'company_published_investors';
if not exists(select 1 from investor_companies j join companies c on c.id=j.company_id join investor_research i on i.id=j.investor_research_id where c.slug='germandrones' and i.slug='klaus-scho' and j.source_url='https://www.germandrones.com/en/contact' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed') then raise exception 'Manifest relationship did not match: germandrones/klaus-scho'; end if;
update investor_companies j set evidence_status='company_published_investors' from companies c, investor_research i where j.company_id=c.id and j.investor_research_id=i.id and c.slug='germandrones' and i.slug='cornelius-toussaint' and j.source_url='https://www.germandrones.com/en/contact' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed' and j.evidence_status<>'company_published_investors';
if not exists(select 1 from investor_companies j join companies c on c.id=j.company_id join investor_research i on i.id=j.investor_research_id where c.slug='germandrones' and i.slug='cornelius-toussaint' and j.source_url='https://www.germandrones.com/en/contact' and j.evidence_status='company_published_investors' and j.relationship_type='portfolio_listed') then raise exception 'Manifest relationship did not match: germandrones/cornelius-toussaint'; end if;
update investor_research set evidence_basis='investor_published_portfolio',evidence_status_label='Investor-published portfolio' where slug='helvetica-capital' and source_dataset='company-funding-research-56' and evidence_basis='company_published_investors';
if (select count(*) from company_funding_rounds f join companies c on c.id=f.company_id join company_funding_round_investors p on p.round_id=f.id join investor_research i on i.id=p.investor_research_id where (c.slug='greenjets' and f.round_key='pre-series-a-2024') or (c.slug='fixar-fixar-aero-llc' and f.round_key in ('latvia-de-minimis-29235','latvia-de-minimis-35511','latvia-de-minimis-39708','latvia-de-minimis-41900','latvia-de-minimis-47434','latvia-de-minimis-50712')))<>14 then raise exception 'Expected 14 manifest participations'; end if;
if not exists(select 1 from company_funding_rounds f join companies c on c.id=f.company_id join company_funding_round_investors p on p.round_id=f.id join investor_research i on i.id=p.investor_research_id where c.slug='greenjets' and f.round_key='pre-series-a-2024' and i.slug='tanglin-venture-partners' and p.role='lead') then raise exception 'Expected Greenjets lead'; end if;
end $funding_checkpoint_56$;
